// Generated by build_phone.py. Practice data lives in IndexedDB, never in this cache.
const PREFIX='sat-pwa:'+self.registration.scope+':',CACHE=PREFIX+'aa3847b64e774641';
const FILES=["./index.html", "./app.js", "./style.css", "./bank-core.js", "./offline.js", "./sync-engine.js", "./cloud.js", "./cloud-config.js", "./vendor/supabase.js", "./vendor/SUPABASE-LICENSE", "./seed.json", "./math-seed.json", "./manifest.webmanifest", "./icon-192.png", "./icon-512.png"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES))));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith(PREFIX)&&name!==CACHE)await caches.delete(name);await self.clients.claim();})()));
